<template><div class="ui-quota"><div><span>{{ label }}</span><strong class="ui-numeric">{{ used }} / {{ total }}</strong></div><UiProgressBar :value="percent" :show-value="false" :tone="tone"/><small v-if="resetText">{{ resetText }}</small></div></template>
<script setup lang="ts">import{computed}from'vue';import UiProgressBar from'./UiProgressBar.vue';const props=defineProps<{label:string;used:number;total:number;resetText?:string}>();const percent=computed(()=>props.total?Math.min(100,props.used/props.total*100):0);const tone=computed<'danger'|'warning'|'neutral'>(()=>percent.value>=90?'danger':percent.value>=70?'warning':'neutral');</script>
<style scoped>.ui-quota{display:grid;gap:7px}.ui-quota>div{display:flex;justify-content:space-between;gap:12px;color:var(--ui-text-muted);font-size:12px}.ui-quota strong{color:var(--ui-text);font-weight:500}.ui-quota small{color:var(--ui-text-soft);font-size:11px}</style>
